import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';

export const MANAGED_MARKER = 'generated by ui-ux-magec';
export const BLOCK_START = '<!-- ui-ux-magec:start -->';
export const BLOCK_END = '<!-- ui-ux-magec:end -->';

/**
 * One file change. Generated files carry a marker; files without it belong to the user and are never
 * overwritten (status "conflict") unless `force` is set.
 */
export type FileAction =
  | { kind: 'managed-file'; path: string; content: string }
  | { kind: 'json-merge'; path: string; pointer: string[]; key: string; value: unknown }
  | { kind: 'text-block'; path: string; block: string; start?: string; end?: string };

export type ActionStatus = 'create' | 'update' | 'unchanged' | 'conflict';

export interface PlannedAction {
  action: FileAction;
  status: ActionStatus;
  reason?: string;
  next?: string;
}

function readOr(path: string): string | null {
  return existsSync(path) ? readFileSync(path, 'utf8') : null;
}

function stableJson(v: unknown): string {
  return JSON.stringify(v);
}

/** Computes what applying each action would do, without writing anything. */
export function planActions(actions: FileAction[], opts: { force?: boolean } = {}): PlannedAction[] {
  return actions.map((a): PlannedAction => {
    const current = readOr(a.path);
    if (a.kind === 'managed-file') {
      if (current === null) return { action: a, status: 'create', next: a.content };
      if (current === a.content) return { action: a, status: 'unchanged' };
      if (!current.includes(MANAGED_MARKER) && !opts.force) return { action: a, status: 'conflict', reason: 'file exists and was not generated by ui-ux-magec' };
      return { action: a, status: 'update', next: a.content };
    }
    if (a.kind === 'json-merge') {
      let doc: Record<string, unknown> = {};
      if (current !== null) {
        try {
          doc = JSON.parse(current) as Record<string, unknown>;
        } catch {
          return { action: a, status: 'conflict', reason: 'existing file is not valid JSON' };
        }
      }
      let node = doc;
      for (const k of a.pointer) {
        const child = node[k];
        if (child === undefined) node[k] = {};
        else if (typeof child !== 'object' || child === null || Array.isArray(child)) return { action: a, status: 'conflict', reason: `"${a.pointer.join('.')}" is not an object` };
        node = node[k] as Record<string, unknown>;
      }
      const existing = node[a.key];
      if (existing !== undefined && stableJson(existing) === stableJson(a.value)) return { action: a, status: 'unchanged' };
      if (existing !== undefined && !opts.force) return { action: a, status: 'conflict', reason: `"${[...a.pointer, a.key].join('.')}" already exists with a different configuration` };
      node[a.key] = a.value;
      return { action: a, status: current === null ? 'create' : 'update', next: JSON.stringify(doc, null, 2) + '\n' };
    }
    const start = a.start ?? BLOCK_START;
    const end = a.end ?? BLOCK_END;
    const block = `${start}\n${a.block.trim()}\n${end}`;
    if (current === null) return { action: a, status: 'create', next: block + '\n' };
    const i = current.indexOf(start);
    const j = current.indexOf(end);
    if (i >= 0 && j > i) {
      const next = current.slice(0, i) + block + current.slice(j + end.length);
      return next === current ? { action: a, status: 'unchanged' } : { action: a, status: 'update', next };
    }
    return { action: a, status: 'update', next: current.replace(/\s*$/, '') + '\n\n' + block + '\n' };
  });
}

export function applyPlanned(planned: PlannedAction[]): PlannedAction[] {
  for (const p of planned) {
    if ((p.status === 'create' || p.status === 'update') && p.next !== undefined) {
      mkdirSync(dirname(p.action.path), { recursive: true });
      writeFileSync(p.action.path, p.next);
    }
  }
  return planned;
}

export function describePlanned(planned: PlannedAction[], base: string): string[] {
  return planned.map((p) => `${p.status.padEnd(9)} ${relative(base, p.action.path) || p.action.path}${p.reason ? `  (${p.reason})` : ''}`);
}

export function joinPath(...parts: string[]): string {
  return join(...parts);
}
